from guide_data import T

PROS = T("장점", "Pros", "長所", "Ventajas", "Avantages")
CONS = T("단점", "Cons", "短所", "Inconvenientes", "Inconvénients")
FOR = T("이런 분께", "Best for", "こんな人に", "Ideal para", "Idéal pour")
BUY = T("구매하기", "Buy", "購入する", "Comprar", "Acheter")

def area(key, name, pros, cons, fr):
    return {"key": key, "name": name, "link": "", "pros": pros, "cons": cons, "for": fr}

def region(h, sub, opts):
    return {"type": "compare", "icon": "bed", "h": h, "sub": sub, "pros": PROS, "cons": CONS, "for": FOR, "buy": BUY, "opts": opts}

